            function isArulApplyUrl(href) {
                return /^https:\/\/(www\.)?arulondon2\.org(\/|$)/i.test(href);
            }

            function getApplyNowHandlerUrl(href) {
                return "/_ajax/applyNow.ashx?redirectUrl=" + encodeURIComponent(addCurrentTrackingParams(href));
            }

            function addCurrentTrackingParams(href) {
                var currentQuery = window.location.search.replace(/^\?/, "");

                if (!currentQuery) {
                    return href;
                }

                var link = document.createElement("a");
                var targetQueryParts;
                var trackingParams = [
                    "_gl", "gclid", "gbraid", "wbraid", "fbclid", "msclkid",
                    "utm_source", "utm_medium", "utm_campaign", "utm_content", "utm_term", "utm_id",
                    "utm_source_platform", "utm_creative_format", "utm_marketing_tactic"
                ];

                link.href = href;
                targetQueryParts = link.search ? link.search.replace(/^\?/, "").split("&") : [];

                $.each(trackingParams, function (_, name) {
                    var currentMatch = currentQuery.match(new RegExp("(^|&)" + name + "=([^&]*)", "i"));
                    var targetMatch = link.search.replace(/^\?/, "").match(new RegExp("(^|&)" + name + "=", "i"));

                    if (currentMatch && !targetMatch) {
                        targetQueryParts.push(name + "=" + currentMatch[2]);
                    }
                });

                link.search = targetQueryParts.length ? "?" + targetQueryParts.join("&") : "";

                return link.href;
            }

            function prepareApplyNowLink(link) {
                var href = $(link).attr("href");

                if (isArulApplyUrl(href)) {
                    $(link).attr("href", getApplyNowHandlerUrl(href));
                }
            }

            $(document).ready(function () {
                $(document).on("mousedown contextmenu auxclick", "a[href]", function (e) {
                    if (e.type === "contextmenu" || e.type === "auxclick" || e.which > 1) {
                        prepareApplyNowLink(this);
                    }
                });

                $(document).on("click", "a[href]", function (e) {
                    var link = this;
                    var href = $(link).attr("href");

                    if (isArulApplyUrl(href)) {
                        e.preventDefault();

                        window.setTimeout(function () {
                            var updatedHref = $(link).attr("href");
                            window.location.href = getApplyNowHandlerUrl(updatedHref);
                        }, 0);
                    }
                });
            });

